import{_ as n,o as s,c as a,e as i}from"./app.547295de.js";const _={},h=i(`<div class="sd-guide"><div class="sd-guide-pager"><input type="radio" name="sd-guide-page" id="sd-guide-p1" class="sd-guide-pager__input" checked><input type="radio" name="sd-guide-page" id="sd-guide-p2" class="sd-guide-pager__input"><nav class="sd-guide-pager__nav" aria-label="新手上路分页"><label for="sd-guide-p1" class="sd-guide-pager__tab">① 新手上路</label><label for="sd-guide-p2" class="sd-guide-pager__tab">② 图像编辑数据集</label></nav><div class="sd-guide-pager__panels"><div class="sd-guide-pager__panel sd-guide-pager__panel--1"><div class="sd-guide-intro"><div class="sd-guide-intro__art" aria-hidden="true"><img src="/assets/guide-mascot.webp?v=20260525-nt5" alt="" loading="lazy" decoding="async"></div><div class="sd-guide-intro__body"><h2 id="新手上路" tabindex="-1"><a class="header-anchor" href="#新手上路" aria-hidden="true">#</a> 新手上路</h2><ol><li><strong>准备数据</strong>：训练图片 + 同名 <code>.txt</code> 标签；可用「工具与调试 → 数据集打标」。</li><li><strong>选择训练类型</strong>（侧栏「训练」）：<ul><li><a href="/lora/sd3.html"><strong>Anima</strong></a> — 文生图 LoRA（推荐）</li><li><a href="/lora/anima-edit.html"><strong>Anima Edit</strong></a> — 图像编辑（Target + Reference）</li><li><a href="/lora/flux.html"><strong>Flux</strong></a></li><li><a href="/lora/master.html"><strong>Stable Diffusion</strong></a> — 默认 SDXL</li><li><a href="/dreambooth/index.html"><strong>Dreambooth 训练</strong></a></li></ul></li><li><strong>图像编辑数据集</strong>：见本页 <a href="/help/guide.html#anima-edit-dataset">② 图像编辑数据集</a> 示意图。</li><li><strong>填写参数并开训</strong>：中栏表单 → 右栏「开始训练」。</li><li><strong>查看进度</strong>：<a href="/monitor/" target="_blank" rel="noopener noreferrer">训练监控</a>、<a href="/tensorboard/">Tensorboard</a>。</li></ol></div></div><section class="sd-guide-migrate"><h2 id="从秋叶版迁移" tabindex="-1"><a class="header-anchor" href="#从秋叶版迁移" aria-hidden="true">#</a> 从秋叶版迁移</h2><p>若你使用过 <strong>Akegarasu/lora-scripts</strong>（秋叶一键包），本版主要变化：</p><ul><li><strong>品牌</strong>：项目名 <strong>lora-scripts-next</strong> / Next Trainer，侧栏按「训练 / 工具 / 帮助 / 其他」分组。</li><li><strong>导航</strong>：LoRA 下为 Anima、<strong>Anima Edit</strong>、Flux、Stable Diffusion；SD1.5 精简页：<a href="/lora/basic.html">/lora/basic.html</a>。</li><li><strong>Anima</strong>：原 SD3 入口改为 Anima（Qwen + T5 + DiT）。</li><li><strong>监控</strong>：独立 <a href="/monitor/" target="_blank" rel="noopener noreferrer">训练监控页</a>、Loss 曲线、<code>/train-log</code> 日志流。</li><li>更多版本说明见 <a href="/other/changelog.html">更新日志</a>。</li></ul></section></div><div class="sd-guide-pager__panel sd-guide-pager__panel--2"><section class="sd-guide-dataset" id="anima-edit-dataset"><h2 tabindex="-1"><a class="header-anchor" href="#anima-edit-dataset" aria-hidden="true">#</a> Anima Edit · 数据集怎么放</h2><p>训练需要<strong>两个目录</strong>：目标图 <code>target/</code> 与参考图 <code>reference/</code>。在 Anima Edit 训练页分别填入「目标图目录」「参考图目录」。</p><p>左侧「参考图布局」选<strong>单张参考图</strong>或<strong>双张参考图</strong>，目录结构不同：</p><div class="sd-guide-dataset__block"><h3>单张参考图</h3><p class="sd-guide-dataset__hint">参考根目录下与 target <strong>同名</strong> 一张图（如 <code>target/a.png</code> → <code>reference/a.png</code>）。标签 <code>.txt</code> / <code>.json</code> 放在 target 侧。</p><pre class="sd-guide-dataset__tree">my_dataset/
├── target/              ← 表单「目标图目录」
│   ├── a.png
│   ├── a.txt
│   └── b.png
└── reference/           ← 表单「参考图目录」
    ├── a.png            （与 target 同名）
    └── b.png</pre></div><div class="sd-guide-dataset__block"><h3>双张参考图</h3><p class="sd-guide-dataset__hint">每个样本在 reference 下建<strong>与 target 文件名同名的文件夹</strong>，里面放 2 张图（按文件名排序取前 2 张）。</p><pre class="sd-guide-dataset__tree">my_dataset/
├── target/              ← 表单「目标图目录」
│   ├── a.png
│   └── a.txt
└── reference/           ← 表单「参考图目录」
    └── a/               ← 文件夹名 = target 文件名（无扩展名）
        ├── 1.png
        └── 2.png</pre></div><p class="sd-guide-dataset__foot">文生图 LoRA 请用侧栏「Anima」页；仅图像编辑使用 Anima Edit。</p><p><a class="sd-home-portal sd-home-portal--primary" href="/lora/anima-edit.html"><span class="sd-home-portal__title">返回 Anima Edit 训练页</span><span class="sd-home-portal__desc">填写路径并开始训练</span></a></p></section></div></div></div></div>`);function u(){return s(),a("div",null,[h])}var x=n(_,[["render",u],["__file","guide.html.vue"]]);export{x as default};